#!/usr/bin/env bash
#
# Repair code-signing in the Xcode project generated by make-safari-app.sh.
#
# Two problems appear when you pick a signing team in Xcode's GUI:
#
#   1. "Embedded binary is not signed with the same certificate as the parent
#      app." Xcode writes DEVELOPMENT_TEAM into the app target only. The
#      extension target is left without a team, so it falls back to ad-hoc
#      signing ("-") and no longer matches its parent.
#
#   2. The converter title-cases the app's bundle identifier but leaves the
#      extension's lowercase, so the extension's ID is no longer nested inside
#      the app's. Xcode rejects the app as an invalid container for its
#      embedded binary. Fixing (1) alone tends to surface this one next.
#
#   ./scripts/fix-safari-project-signing.sh [--team TEAMID] [--project DIR]
#
# Defaults to the project at ../autokosten-berekenaar-safari and auto-detects
# the team from your installed Apple Development certificate.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PROJECT_DIR="$(cd "${REPO_ROOT}/.." && pwd)/autokosten-berekenaar-safari"
TEAM=""
APP_BUNDLE_ID="nl.jortdejong.autokosten-berekenaar"

while [[ $# -gt 0 ]]; do
  case "$1" in
    --team)    TEAM="$2"; shift 2 ;;
    --project) PROJECT_DIR="$2"; shift 2 ;;
    -h|--help) sed -n '2,20p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *) echo "unknown option: $1" >&2; exit 1 ;;
  esac
done

# --- Locate the project file ------------------------------------------------

XCproj="$(find "${PROJECT_DIR}" -name "project.xcproj" -o -name "project.pbxproj" 2>/dev/null | head -1)"
if [[ -z "${XCproj}" ]]; then
  echo "error: no Xcode project found under ${PROJECT_DIR}" >&2
  exit 1
fi

if [[ "${XCproj}" == *".pbxproj" ]]; then
  cat >&2 <<'MSG'
error: this project uses the older project.pbxproj format, which this script
does not rewrite. Fix it in Xcode instead:

  1. Select the project, then the "Autokosten Berekenaar Extension" target.
  2. Signing & Capabilities > Team: pick the same team as the app target.
  3. Also confirm the extension's bundle identifier is the app's identifier
     with ".Extension" appended.
MSG
  exit 1
fi

# --- Work out the team ------------------------------------------------------

if [[ -z "${TEAM}" ]]; then
  # The team ID lives in the certificate's OU field, NOT in the CN
  # parenthetical. For a certificate like
  #
  #   CN=Apple Development: you@example.com (ABC123CERT), OU=TEAM123456
  #
  # the parenthetical is the certificate identifier and OU is the team.
  # Using the parenthetical yields a team that exists only on paper, and
  # xcodebuild then fails with:
  #   No signing certificate "Mac Development" found ... matching team ID ...
  CERT_CN="$(security find-identity -v -p codesigning 2>/dev/null \
    | grep -oE '"Apple Development: [^"]*"' | tr -d '"' | head -1)"

  if [[ -n "${CERT_CN}" ]]; then
    TEAM="$(security find-certificate -c "${CERT_CN}" -p 2>/dev/null \
      | openssl x509 -noout -subject 2>/dev/null \
      | tr ',' '\n' | sed -n 's/^ *OU=//p' | tr -d ' ' | head -1)"
  fi

  if [[ -z "${TEAM}" ]]; then
    # Fall back to parsing the CN parenthetical, which is right on some
    # older certificates, and warn since it is often the cert ID instead.
    TEAM="$(printf '%s' "${CERT_CN}" | grep -oE '\(([A-Z0-9]+)\)' | tr -d '()')"
    if [[ -n "${TEAM}" ]]; then
      echo "warning: read team '${TEAM}' from the certificate's CN, not OU." >&2
      echo "         Verify it matches your Team ID at developer.apple.com." >&2
    fi
  fi
fi

if [[ -z "${TEAM}" ]]; then
  cat >&2 <<'MSG'
error: could not determine your signing team automatically.

Pass it explicitly — find it in Xcode under Signing & Capabilities, in the
Team dropdown (or at developer.apple.com > Membership):

    ./scripts/fix-safari-project-signing.sh --team XXXXXXXXXX
MSG
  exit 1
fi

EXT_BUNDLE_ID="${APP_BUNDLE_ID}.Extension"

echo "Project:  ${XCproj}"
echo "Team:     ${TEAM}"
echo "App id:   ${APP_BUNDLE_ID}"
echo "Ext id:   ${EXT_BUNDLE_ID}"
echo

cp "${XCproj}" "${XCproj}.bak"
echo "Backup:   ${XCproj}.bak"
echo

TEAM="${TEAM}" APP_ID="${APP_BUNDLE_ID}" EXT_ID="${EXT_BUNDLE_ID}" python3 - "${XCproj}" <<'PY'
import json, os, re, sys

path = sys.argv[1]
team = os.environ["TEAM"]
app_id = os.environ["APP_ID"]
ext_id = os.environ["EXT_ID"]

raw = open(path).read()

# The converter writes JSON with trailing commas; strip them so we can parse.
# We re-serialise afterwards, which is valid JSON that Xcode reads fine.
data = json.loads(re.sub(r",(\s*[}\]])", r"\1", raw))

targets = {t.get("name"): t for t in data.get("targets", [])}
app = next((t for n, t in targets.items() if t.get("product-type") == "application"), None)
ext = next((t for n, t in targets.items() if t.get("product-type") == "app-extension"), None)

if app is None or ext is None:
    print("error: could not identify both an app and an app-extension target", file=sys.stderr)
    sys.exit(1)

def setb(target, key, value):
    target.setdefault("build-settings", {})[key] = value

# 1. Same team on both targets, so the embedded binary matches its parent.
for t in (app, ext):
    setb(t, "DEVELOPMENT_TEAM", team)
    setb(t, "CODE_SIGN_STYLE", "Automatic")

# 2. The extension id must be the app id plus ".Extension", or Xcode treats the
#    app as an invalid container for it.
setb(app, "PRODUCT_BUNDLE_IDENTIFIER", app_id)
setb(ext, "PRODUCT_BUNDLE_IDENTIFIER", ext_id)

open(path, "w").write(json.dumps(data, indent=2) + "\n")

for label, t in (("app", app), ("extension", ext)):
    bs = t["build-settings"]
    print(f"  {label:10} team={bs['DEVELOPMENT_TEAM']}  id={bs['PRODUCT_BUNDLE_IDENTIFIER']}")
PY

cat <<'MSG'

Done. In Xcode:

  1. Close and reopen the project (Xcode caches the old settings).
  2. Select the project > both targets > Signing & Capabilities, and confirm the
     Team dropdown shows your team for BOTH.
  3. Press Run (⌘R).

If Xcode still reports a team error, set the team in the GUI for both targets —
the GUI is authoritative and will overwrite what this script wrote.
MSG
